    }

    public static int fromBinary(String s) {
        if (s == null || s.isEmpty()) {
            throw new NumberFormatException("Empty string");
        }
        int result = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '0') {
                result = result << 1;
            } else if (c == '1') {
                result = (result << 1) | 1;
            } else {
                throw new NumberFormatException("Invalid binary character: " + c);
            }
        }
        return result;
    }
