import java.util.*;

public class IntList {
    private class Node {
        int value;
        Node next;

        Node(int value) {
            this.value = value;
        }
    }

    private Node head;
    private Node tail;

    public void add(int v) {
        Node newNode = new Node(v);
        if (head == null) {
            head = newNode;
            tail = newNode;
        } else {
            tail.next = newNode;
            tail = newNode;
        }
    }

    public List<Integer> toList() {
        List<Integer> result = new ArrayList<>();
        Node current = head;
        while (current != null) {
            result.add(current.value);
            current = current.next;
        }
        return result;
    }

    public void reverse() {
        Node prev = null;
        Node current = head;
        tail = head;
        while (current != null) {
            Node nextNode = current.next;
            current.next = prev;
            prev = current;
            current = nextNode;
        }
        head = prev;
    }

    public void removeAll(int v) {
        Node dummy = new Node(0);
        dummy.next = head;
        Node current = dummy;

        while (current.next != null) {
            if (current.next.value == v) {
                current.next = current.next.next;
            } else {
                current = current.next;
            }
        }

        head = dummy.next;

        // Update tail if necessary
        if (head == null) {
            tail = null;
        } else {
            Node temp = head;
            while (temp.next != null) {
                temp = temp.next;
            }
            tail = temp;
        }
    }
}
