import java.util.*;

public class Trie {
    private class TrieNode {
        private Map<Character, TrieNode> children = new TreeMap<>();
        private boolean isEndOfWord = false;
    }

    private final TrieNode root;

    public Trie() {
        root = new TrieNode();
    }

    public void insert(String w) {
        TrieNode current = root;
        for (char c : w.toCharArray()) {
            current = current.children.computeIfAbsent(c, k -> new TrieNode());
        }
        current.isEndOfWord = true;
    }

    public boolean contains(String w) {
        TrieNode node = findNode(w);
        return node != null && node.isEndOfWord;
    }

    public boolean startsWith(String p) {
        return findNode(p) != null;
    }

    public List<String> withPrefix(String p) {
        List<String> result = new ArrayList<>();
        TrieNode node = findNode(p);
        if (node != null) {
            collectWords(node, new StringBuilder(p), result);
        }
        return result;
    }

    private TrieNode findNode(String s) {
        TrieNode current = root;
        for (char c : s.toCharArray()) {
            current = current.children.get(c);
            if (current == null) return null;
        }
        return current;
    }

    private void collectWords(TrieNode node, StringBuilder prefix, List<String> result) {
        if (node.isEndOfWord) {
            result.add(prefix.toString());
        }
        for (Map.Entry<Character, TrieNode> entry : node.children.entrySet()) {
            prefix.append(entry.getKey());
            collectWords(entry.getValue(), prefix, result);
            prefix.setLength(prefix.length() - 1);
        }
    }
}
