public class Queens {
    public static int count(int n) {
        if (n <= 0) return 0;
        return solve(0, 0, 0, 0, n);
    }

    private static int solve(int row, int cols, int diag1, int diag2, int n) {
        if (row == n) {
            return 1;
        }

        int count = 0;
        // All bits set to 1 for the size of the board
        int allQueensSet = (1 << n) - 1;

        // Find available positions in the current row
        // A position is available if it's not in cols, diag1, or diag2
        int availablePositions = allQueensSet & ~(cols | diag1 | diag2);

        while (availablePositions != 0) {
            // Extract the lowest set bit (the next position to try)
            int position = availablePositions & -availablePositions;

            // Remove this position from available positions
            availablePositions ^= position;

            // Move to the next row
            // diag1 shifts left (covers next row's diagonal)
            // diag2 shifts right (covers next row's diagonal)
            count += solve(
                row + 1,
                cols | position,
                (diag1 | position) << 1,
                (diag2 | position) >>> 1,
                n
            );
        }

        return count;
    }
}
