import java.util.*;

public class Perms {
    public static List<List<Integer>> of(List<Integer> xs) {
        List<List<Integer>> result = new ArrayList<>();
        if (xs.isEmpty()) {
            result.add(new ArrayList<>());
            return result;
        }
        backtrack(xs, new ArrayList<>(), new boolean[xs.size()], result);
        return result;
    }

    private static void backtrack(List<Integer> xs, List<Integer> current, boolean[] used, List<List<Integer>> result) {
        if (current.size() == xs.size()) {
            result.add(new ArrayList<>(current));
            return;
        }

        for (int i = 0; i < xs.size(); i++) {
            if (!used[i]) {
                used[i] = true;
                current.add(xs.get(i));
                backtrack(xs, current, used, result);
                current.remove(current.size() - 1);
                used[i] = false;
            }
        }
    }
}
