public class Subsets {
    public static int countWithSum(int[] a, int target) {
        int n = a.length;
        int count = 0;
        // Since n <= 20, we can use bitmasking to iterate through all 2^n subsets
        int totalSubsets = 1 << n;

        for (int i = 0; i < totalSubsets; i++) {
            long currentSum = 0;
            for (int j = 0; j < n; j++) {
                // Check if the j-th element is included in the i-th subset
                if ((i & (1 << j)) != 0) {
                    currentSum += a[j];
                }
            }
            if (currentSum == target) {
                count++;
            }
        }

        return count;
    }
}
