import java.util.HashMap;
import java.util.Map;
import java.util.function.LongSupplier;

public class TtlCache<K, V> {
    private final LongSupplier clock;
    private final long ttlMillis;
    private final Map<K, CacheEntry<V>> cache = new HashMap<>();

    private static class CacheEntry<V> {
        final V value;
        final long timestamp;

        CacheEntry(V value, long timestamp) {
            this.value = value;
            this.timestamp = timestamp;
        }
    }

    public TtlCache(LongSupplier clock, long ttlMillis) {
        this.clock = clock;
        this.ttlMillis = ttlMillis;
    }

    public void put(K k, V v) {
        cache.put(k, new CacheEntry<>(v, clock.getAsLong()));
    }

    public V get(K k) {
        CacheEntry<V> entry = cache.get(k);
        if (entry == null) {
            return null;
        }
        if (clock.getAsLong() - entry.timestamp >= ttlMillis) {
            cache.remove(k);
            return null;
        }
        return entry.value;
    }

    public int size() {
        long now = clock.getAsLong();
        int count = 0;
        // Use iterator to allow removal during traversal if needed, 
        // though here we just count valid ones.
        for (Map.Entry<K, CacheEntry<V>> entry : cache.entrySet()) {
            if (now - entry.getValue().timestamp < ttlMillis) {
                count++;
            }
        }
        return count;
    }
}
