public class RomanParse {
    private static final Map<Character, Integer> ROMAN_MAP = new HashMap<>();

    static {
        ROMAN_MAP.put('I', 1);
        ROMAN_MAP.put('V', 5);
        ROMAN_MAP.put('X', 10);
        ROMAN_MAP.put('L', 50);
        ROMAN_MAP.put('C', 100);
        ROMAN_MAP.put('D', 500);
        ROMAN_MAP.put('M', 1000);
    }

    public static int parse(String s) {
        if (s == null || s.isEmpty()) {
            throw new IllegalArgumentException("Input string is empty or null");
        }

        int total = 0;
        int prevValue = 0;

        // Process from right to left to easily handle subtractive notation
        for (int i = s.length() - 1; i >= 0; i--) {
            char c = s.charAt(i);
            if (!ROMAN_MAP.containsKey(c)) {
                throw new IllegalArgumentException("Illegal character: " + c);
            }

            int currentValue = ROMAN_MAP.get(c);

            if (currentValue < prevValue) {
                total -= currentValue;
            } else {
                total += currentValue;
            }
            prevValue = currentValue;
        }

        return total;
    }
}
