    }

    public void remove(String sku, int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("Quantity to remove must be positive");
        }
        Product p = products.get(sku);
        if (p == null) {
            throw new NoSuchElementException("SKU not found: " + sku);
        }
        if (n > p.qty()) {
            throw new IllegalStateException("Insufficient stock for SKU: " + sku);
        }

        int newQty = p.qty() - n;
        if (newQty == 0) {
            products.remove(sku);
        } else {
            products.put(sku, new Product(p.sku(), p.name(), newQty));
        }
    }

    public List<String> lowStock(int threshold) {
        List<String> result = new ArrayList<>();
        for (Product p : products.values()) {
            if (p.qty() < threshold) {
                result.add(p.sku());
            }
        }
        return result;
    }
