import java.util.Collections;
import java.util.Map;

public class Parser {
    private final String s;
    private int p;
    private final Map<String, Long> vars;

    private Parser(String s, Map<String, Long> vars) {
        this.s = s;
        this.vars = vars;
    }

    public static long eval(String s) {
        return eval(s, Collections.emptyMap());
    }

    public static long eval(String s, Map<String, Long> vars) {
        Parser q = new Parser(s, vars);
        long v = q.expr();
        q.ws();
        if (q.p != s.length()) throw new IllegalArgumentException("unexpected input at " + q.p);
        return v;
    }

    private void ws() {
        while (p < s.length() && s.charAt(p) == ' ') p++;
    }

    private long expr() {
        long v = term();
        while (true) {
            ws();
            if (p < s.length() && s.charAt(p) == '+') { p++; v += term(); }
            else if (p < s.length() && s.charAt(p) == '-') { p++; v -= term(); }
            else return v;
        }
    }

    private long term() {
        long v = atom();
        while (true) {
            ws();
            if (p < s.length() && s.charAt(p) == '*') { p++; v *= atom(); }
            else if (p < s.length() && s.charAt(p) == '/') {
                long d = atom();
                if (d == 0) throw new ArithmeticException("/ by zero");
                v /= d;
            } else if (p < s.length() && s.charAt(p) == '%') {
                p++;
                long d = atom();
                if (d == 0) throw new ArithmeticException("/ by zero");
                v %= d;
            } else return v;
        }
    }

    private long atom() {
        ws();
        if (p >= s.length()) throw new IllegalArgumentException("unexpected end");
        char c = s.charAt(p);
        if (c == '(') {
            p++;
            long v = expr();
            ws();
            if (p >= s.length() || s.charAt(p) != ')') throw new IllegalArgumentException("missing )");
            p++;
            return v;
        }
        if (Character.isLetter(c) || c == '_') {
            StringBuilder sb = new StringBuilder();
            if (c == '_') sb.append(s.charAt(p++));
            while (p < s.length() && (Character.isLetterOrDigit(s.charAt(p)) || s.charAt(p) == '_')) {
                sb.append(s.charAt(p++));
            }
            String name = sb.toString();
            if (vars.containsKey(name)) return vars.get(name);
            throw new IllegalArgumentException("unbound variable: " + name);
        }
        if (!Character.isDigit(c)) throw new IllegalArgumentException("unexpected " + c);
        long v = 0;
        while (p < s.length() && Character.isDigit(s.charAt(p))) {
            v = v * 10 + (s.charAt(p++) - '0');
        }
        return v;
    }
}
