import java.util.*;

public class Lexer {
    public static List<String> tokens(String src) {
        List<String> out = new ArrayList<>();
        int i = 0;
        while (i < src.length()) {
            char c = src.charAt(i);

            // Skip whitespace
            if (Character.isWhitespace(c)) {
                i++;
                continue;
            }

            // Handle Comments
            if (c == '/' && i + 1 < src.length()) {
                char next = src.charAt(i + 1);
                if (next == '/') { // Line comment
                    i += 2;
                    while (i < src.length() && src.charAt(i) != '\n') i++;
                    continue;
                } else if (next == '*') { // Block comment
                    i += 2;
                    int start = i;
                    boolean closed = false;
                    while (i + 1 < src.length()) {
                        if (src.charAt(i) == '*' && src.charAt(i + 1) == '/') {
                            i += 2;
                            closed = true;
                            break;
                        }
                        i++;
                    }
                    if (!closed) throw new IllegalArgumentException("Unterminated block comment");
                    continue;
                }
            }

            // Handle String Literals
            if (c == '"') {
                StringBuilder sb = new StringBuilder();
                i++; // skip opening quote
                boolean closed = false;
                while (i < src.length()) {
                    char curr = src.charAt(i);
                    if (curr == '\\' && i + 1 < src.length()) {
                        char next = src.charAt(i + 1);
                        if (next == '"' || next == '\\') {
                            sb.append(next);
                            i += 2;
                            continue;
                        }
                    }
                    if (curr == '"') {
                        closed = true;
                        i++;
                        break;
                    }
                    sb.append(curr);
                    i++;
                }
                if (!closed) throw new IllegalArgumentException("Unterminated string literal");
                out.add("STR:" + sb.toString());
                continue;
            }

            // Handle Identifiers
            if (Character.isLetter(c) || c == '_') {
                int j = i;
                while (j < src.length() && (Character.isLetterOrDigit(src.charAt(j)) || src.charAt(j) == '_')) j++;
                out.add("ID:" + src.substring(i, j));
                i = j;
            } 
            // Handle Numbers
            else if (Character.isDigit(c)) {
                int j = i;
                while (j < src.length() && Character.isDigit(src.charAt(j))) j++;
                out.add("NUM:" + src.substring(i, j));
                i = j;
            } 
            // Handle Two-character Operators
            else if (i + 1 < src.length() && isTwoCharOp(src, i)) {
                out.add("SYM:" + src.substring(i, i + 2));
                i += 2;
            }
            // Handle Single-character Symbols
            else {
                out.add("SYM:" + c);
                i++;
            }
        }
        return out;
    }

    private static boolean isTwoCharOp(String src, int i) {
        String sub = src.substring(i, i + 2);
        return sub.equals("==") || sub.equals("!=") || sub.equals("<=") || 
               sub.equals(">=") || sub.equals("&&") || sub.equals("||");
    }
}
