import java.util.*;

public class IntervalSet {
    private final TreeMap<Integer, Integer> m = new TreeMap<>(); // start -> end (inclusive), disjoint, non-adjacent

    public void add(int lo, int hi) {
        if (lo > hi) throw new IllegalArgumentException("lo > hi");
        Map.Entry<Integer, Integer> e = m.floorEntry(lo);
        if (e != null && e.getValue() >= lo - 1) {
            lo = e.getKey();
            hi = Math.max(hi, e.getValue());
        }
        Map.Entry<Integer, Integer> n;
        while ((n = m.ceilingEntry(lo)) != null && n.getKey() <= hi + 1) {
            hi = Math.max(hi, n.getValue());
            m.remove(n.getKey());
        }
        m.put(lo, hi);
    }

    public void remove(int lo, int hi) {
        if (lo > hi) throw new IllegalArgumentException("lo > hi");
        // Find the interval that starts at or before lo
        Map.Entry<Integer, Integer> e = m.floorEntry(lo);
        if (e != null && e.getValue() >= lo) {
            int start = e.getKey();
            int end = e.getValue();
            m.remove(start);
            // If the interval extends before lo, keep the part [start, lo-1]
            if (start < lo) {
                m.put(start, lo - 1);
            }
            // If the interval extends after hi, keep the part [hi+1, end]
            if (end > hi) {
                m.put(hi + 1, end);
            }
        }

        // Remove/split all intervals that start within [lo, hi]
        Map.Entry<Integer, Integer> n;
        while ((n = m.ceilingEntry(lo)) != null && n.getKey() <= hi) {
            int start = n.getKey();
            int end = n.getValue();
            m.remove(start);
            // If the interval extends beyond hi, keep the part [hi+1, end]
            if (end > hi) {
                m.put(hi + 1, end);
            }
        }
    }

    public boolean contains(int x) {
        Map.Entry<Integer, Integer> e = m.floorEntry(x);
        return e != null && e.getValue() >= x;
    }

    public long totalLength() {
        long total = 0;
        for (Map.Entry<Integer, Integer> entry : m.entrySet()) {
            total += (long) entry.getValue() - entry.getKey() + 1;
        }
        return total;
    }

    public List<int[]> intervals() {
        List<int[]> out = new ArrayList<>();
        m.forEach((k, v) -> out.add(new int[]{k, v}));
        return out;
    }
}
