        if (e instanceof Add a) return eval(a.l()) + eval(a.r());
        if (e instanceof Mul m) return eval(m.l()) * eval(m.r());
        throw new AssertionError();
    }

    static String show(Expr e) {
        if (e instanceof Num n) return String.valueOf(n.v());
        if (e instanceof Add a) return "(" + show(a.l()) + " + " + show(a.r()) + ")";
        if (e instanceof Mul m) return "(" + show(m.l()) + " * " + show(m.r()) + ")";
        throw new AssertionError();
    }

    static Expr simplify(Expr e) {
        if (e instanceof Num) return e;

        if (e instanceof Add a) {
            Expr l = simplify(a.l());
            Expr r = simplify(a.r());

            if (l instanceof Num ln && r instanceof Num rn) return new Num(ln.v() + rn.v());
            if (l instanceof Num ln && ln.v() == 0) return r;
            if (r instanceof Num rn && rn.v() == 0) return l;
            return new Add(l, r);
        }

        if (e instanceof Mul m) {
            Expr l = simplify(m.l());
            Expr r = simplify(m.r());

            if (l instanceof Num ln && r instanceof Num rn) return new Num(ln.v() * rn.v());
            if (l instanceof Num ln) {
                if (ln.v() == 0) return new Num(0);
                if (ln.v() == 1) return r;
            }
            if (r instanceof Num rn) {
                if (rn.v() == 0) return new Num(0);
                if (rn.v() == 1) return l;
            }
            return new Mul(l, r);
        }

        throw new AssertionError();
    }
