import java.util.*;
import java.util.stream.Collectors;

public class CsvWriter {
    public static String formatLine(List<String> fields) {
        return fields.stream()
            .map(field -> {
                if (field == null) return "";
                boolean needsQuotes = field.contains(",") || field.contains("\"") || field.contains("\n") || field.contains("\r");
                String escaped = field.replace("\"", "\"\"");
                if (needsQuotes) {
                    return "\"" + escaped + "\"";
                }
                return escaped;
            })
            .collect(Collectors.joining(","));
    }

    public static String formatAll(List<List<String>> rows) {
        if (rows == null || rows.isEmpty()) return "";
        return rows.stream()
            .map(CsvWriter::formatLine)
            .collect(Collectors.joining("\n"));
    }
}
