import java.util.*;

public class BinTree {
    public static class Node {
        public final int val;
        public Node left, right;
        public Node(int val, Node left, Node right) {
            this.val = val;
            this.left = left;
            this.right = right;
        }
    }

    public static List<Integer> inorder(Node n) {
        List<Integer> out = new ArrayList<>();
        walkInorder(n, out);
        return out;
    }

    private static void walkInorder(Node n, List<Integer> out) {
        if (n == null) return;
        walkInorder(n.left, out);
        out.add(n.val);
        walkInorder(n.right, out);
    }

    public static List<Integer> preorder(Node n) {
        List<Integer> out = new ArrayList<>();
        walkPreorder(n, out);
        return out;
    }

    private static void walkPreorder(Node n, List<Integer> out) {
        if (n == null) return;
        out.add(n.val);
        walkPreorder(n.left, out);
        walkPreorder(n.right, out);
    }

    public static List<Integer> postorder(Node n) {
        List<Integer> out = new ArrayList<>();
        walkPostorder(n, out);
        return out;
    }

    private static void walkPostorder(Node n, List<Integer> out) {
        if (n == null) return;
        walkPostorder(n.left, out);
        walkPostorder(n.right, out);
        out.add(n.val);
    }

    public static List<List<Integer>> levelOrder(Node n) {
        List<List<Integer>> result = new ArrayList<>();
        if (n == null) return result;
        Queue<Node> queue = new LinkedList<>();
        queue.add(n);
        while (!queue.isEmpty()) {
            int size = queue.size();
            List<Integer> level = new ArrayList<>();
            for (int i = 0; i < size; i++) {
                Node curr = queue.poll();
                level.add(curr.val);
                if (curr.left != null) queue.add(curr.left);
                if (curr.right != null) queue.add(curr.right);
            }
            result.add(level);
        }
        return result;
    }

    public static int maxDepth(Node n) {
        if (n == null) return 0;
        return 1 + Math.max(maxDepth(n.left), maxDepth(n.right));
    }

    public static boolean isSymmetric(Node n) {
        return isMirror(n, n);
    }

    private static boolean isMirror(Node t1, Node t2) {
        if (t1 == null && t2 == null) return true;
        if (t1 == null || t2 == null) return false;
        return (t1.val == t2.val)
                && isMirror(t1.left, t2.right)
                && isMirror(t1.right, t2.left);
    }
}
